const D = { energy: .5, scale: 1, speed: 1, density: .45, bruise: .5, hue: 205, x: .5, y: .45, style: 'impact', seed: 0, alpha: 55 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A pane of glass between the audience and the scene, quietly failing.
// This is an OVERLAY: it draws nothing but crack lines, a soft bruise and a few glints, so the
// scene behind stays legible. Default alpha is low and coverage is a few percent of the frame.
// Anti-strobe doctrine: an impact FADES IN over ~1.4s and its cracks CREEP outward over a few
// seconds — glass under load creeps, so this is honest as well as safe. Nothing ever snaps.
// Anti-convergence: sites live staggered lives and anneal away, so the pane is never "done".
const u = Math.min(width, height);
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const tt = K.t, style = P.style;
const dr1 = Math.sin(tt * 0.061), dr2 = Math.sin(tt * 0.143 + 1.7), dr3 = Math.sin(tt * 0.229 + 0.4);

// ---- site lifecycles (tolerate t0 resets: K.t can jump backwards at any time) ----
if (!S.sites || S.seedUsed !== P.seed || S.lastT == null || tt < S.lastT - 0.5) {
  S.seedUsed = P.seed; S.sites = []; S.next = tt - 6; S.ctr = 0;
}
S.lastT = tt;
const LIFE = 30 + (1 - P.density) * 26;
const GAP = (9.0 - P.density * 5.5) / Math.max(0.2, P.speed);
const MAXS = Math.max(1, Math.round(1 + P.density * 4));
while (S.next <= tt && S.sites.length < MAXS + 2) {
  const c = S.ctr++;
  S.sites.push({
    t0: S.next, c: c,
    x: P.x + (fr(c * 13.3 + 1) - 0.5) * 0.78,
    y: P.y + (fr(c * 13.3 + 2) - 0.5) * 0.72,
    n: 5 + Math.floor(fr(c * 13.3 + 3) * 8),
    r: 0.13 + 0.20 * fr(c * 13.3 + 4),
    sp: 0.5 + 0.7 * fr(c * 13.3 + 5)
  });
  S.next += GAP * (0.6 + 0.8 * fr(c * 13.3 + 6));
}
S.sites = S.sites.filter(s => tt - s.t0 < LIFE);
if (S.next > tt + GAP * 4) S.next = tt;

const ctx = drawingContext;
const aa = Math.max(0, Math.min(100, P.alpha)) / 100;
const hb = ((P.hue % 360) + 360) % 360;
// crack ink + specular lip per style
let INK, SPEC, BRU;
if (style === 'ink') { INK = [38, 30, 22]; SPEC = [250, 244, 226]; BRU = [120, 104, 82]; }
else if (style === 'frost') { INK = [188, 236, 254]; SPEC = [238, 252, 255]; BRU = [150, 210, 240]; }
else if (style === 'outline') { INK = [96, 214, 236]; SPEC = [180, 240, 250]; BRU = [40, 120, 150]; }
else if (style === 'windscreen') { INK = [28, 30, 34]; SPEC = [246, 240, 226]; BRU = [226, 224, 218]; }
else { INK = [10, 12, 16]; SPEC = [214, 236, 255]; BRU = [180, 206, 232]; }

// Where the room's reflection currently sits on the pane. Drifts on incommensurate rates
// (~48s and ~103s beats), so it never returns to the same place.
const REFX = (0.5 + 0.26 * Math.sin(tt * 0.131) + 0.16 * Math.sin(tt * 0.061 + 1.1)) * width;
const REFY = (0.5 + 0.22 * Math.cos(tt * 0.097 + 0.7) + 0.13 * Math.sin(tt * 0.043 + 2.2)) * height;

ctx.save();
ctx.lineCap = 'round'; ctx.lineJoin = 'round';
for (const s of S.sites) {
  const age = tt - s.t0;
  if (age < 0) continue;
  const cx = s.x * width, cy = s.y * height;
  const reach = s.r * u * Math.max(0.4, P.scale);
  // Two-stage growth, both real: a fast dynamic burst that arrests within ~1.5s, then
  // SUBCRITICAL CREEP for the rest of the site's life — glass genuinely keeps growing its
  // cracks for as long as it is loaded. It also means the cracks are visibly longer across
  // any 8s window instead of saturating early and reading as a frozen decal.
  const fast = Math.min(1, Math.pow(age * s.sp * P.speed * 0.7, 0.6));
  const creep = Math.min(1, (age * P.speed) / (LIFE * 0.8));
  const L = reach * (0.42 * fast + 0.58 * creep);
  if (L < u * 0.008) continue;
  const fin = Math.min(1, age / 1.4);                       // no impact ever appears in one frame
  const fout = Math.min(1, Math.max(0, (LIFE - age) / (LIFE * 0.85)));
  const op = fin * fout * (0.35 + 0.65 * P.energy) * aa;
  if (op < 0.010) continue;
  const nr = Math.max(3, Math.round(s.n * (0.5 + P.density * 0.7)));

  // ---- the bruise: laminated glass goes milky around a strike. Soft, wide, very low alpha —
  // it is what keeps the overlay reading as GLASS rather than as scratches on the lens. ----
  if (P.bruise > 0.01 && style !== 'outline') {
    const br = L * (0.42 + 0.22 * Math.sin(tt * 0.23 + s.c));
    const gd = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(1, br));
    const bi = P.bruise * op * (style === 'windscreen' ? 0.50 : 0.28);
    gd.addColorStop(0, 'rgba(' + BRU[0] + ',' + BRU[1] + ',' + BRU[2] + ',' + bi.toFixed(3) + ')');
    gd.addColorStop(1, 'rgba(' + BRU[0] + ',' + BRU[1] + ',' + BRU[2] + ',0)');
    ctx.fillStyle = gd; ctx.fillRect(cx - br, cy - br, br * 2, br * 2);
  }

  // ---- radials ----
  const paths = [];
  for (let j = 0; j < nr; j++) {
    const ang = (j / nr) * 6.2831 + fr(s.c * 5.1 + j) * 0.7;
    const ll = L * (0.5 + 0.5 * fr(s.c * 3.7 + j * 2.3));
    const pts = [cx, cy];
    let px = cx, py = cy, a = ang;
    for (let k = 1; k <= 6; k++) {
      a += (fr(s.c * 91.7 + j * 17.3 + k * 3.1) - 0.5) * 0.34;
      px += Math.cos(a) * (ll / 6); py += Math.sin(a) * (ll / 6);
      pts.push(px, py);
    }
    paths.push(pts);
  }
  ctx.beginPath();
  for (const p of paths) { ctx.moveTo(p[0], p[1]); for (let k = 2; k < p.length; k += 2) ctx.lineTo(p[k], p[k + 1]); }
  ctx.strokeStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + (op * 0.8).toFixed(3) + ')';
  ctx.lineWidth = Math.max(0.6, u * 0.0018 * (0.5 + P.energy * 0.9));
  ctx.stroke();
  if (style !== 'outline') {   // the bright lip that reads as a fracture in glass
    // a crack lip only fires where light actually rakes it, so the lips flare and fade as
    // the room's reflection wanders over them
    const dref = Math.hypot(cx - REFX, cy - REFY) / u;
    const rake = 0.45 + 0.85 * Math.exp(-dref * dref * 1.6);
    ctx.beginPath();
    const off = u * 0.0013;
    for (const p of paths) { ctx.moveTo(p[0] + off, p[1] - off); for (let k = 2; k < p.length; k += 2) ctx.lineTo(p[k] + off, p[k + 1] - off); }
    ctx.strokeStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + Math.min(0.95, op * 0.42 * rake).toFixed(3) + ')';
    ctx.lineWidth = Math.max(0.4, u * 0.0009); ctx.stroke();
  }

  // ---- concentrics, lagging behind the running tips ----
  ctx.beginPath();
  let any = false;
  for (let q = 1; q <= 3; q++) {
    const rr = reach * (q / 3.6) * (0.55 + 0.45 * fr(s.c + q * 9.1));
    if (rr > L * 0.84) continue;
    any = true;
    for (let j = 0; j < nr; j++) {
      const a0 = (j / nr) * 6.2831 + fr(s.c * 5.1 + j) * 0.7;
      const a1 = ((j + 1) / nr) * 6.2831 + fr(s.c * 5.1 + j + 1) * 0.7;
      const am = (a0 + a1) * 0.5, bow = rr * 1.12;
      ctx.moveTo(cx + Math.cos(a0) * rr, cy + Math.sin(a0) * rr);
      ctx.quadraticCurveTo(cx + Math.cos(am) * bow, cy + Math.sin(am) * bow, cx + Math.cos(a1) * rr, cy + Math.sin(a1) * rr);
    }
  }
  if (any) {
    ctx.strokeStyle = 'rgba(' + INK[0] + ',' + INK[1] + ',' + INK[2] + ',' + (op * 0.5).toFixed(3) + ')';
    ctx.lineWidth = Math.max(0.4, u * 0.0011); ctx.stroke();
  }

  // ---- crumb zone + a glint crawling out along one radial (small, soft, never a flash) ----
  if (style !== 'outline') {
    const cz = u * 0.008 * (0.7 + 0.6 * fr(s.c + 3)) * Math.min(1, age * 0.8);
    ctx.beginPath(); ctx.arc(cx, cy, cz, 0, 6.2831);
    ctx.fillStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + (op * 0.45).toFixed(3) + ')';
    ctx.fill();
  }
  const gi = (tt * 0.33 * P.speed + s.c * 0.37) % 1;
  const ga = (Math.floor(tt * 0.17 + s.c) % nr) / nr * 6.2831 + fr(s.c * 5.1) * 0.7;
  ctx.beginPath();
  ctx.arc(cx + Math.cos(ga) * L * gi, cy + Math.sin(ga) * L * gi, u * 0.0045 * (1 - gi * 0.6), 0, 6.2831);
  ctx.fillStyle = 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + (op * 0.55 * (1 - gi) * (0.4 + P.energy)).toFixed(3) + ')';
  ctx.fill();
}

// ---- A wandering reflection on the pane's own surface. A sheet of glass between you and the
// scene always catches the room, so this is honest — and it is what carries the motion floor:
// crack hairlines are far too sparse to move a frame mean on their own, whereas this is a
// broad, very low-alpha veil drifting on incommensurate rates. Polite by construction: it is
// a ~4% wash, it never obscures what is behind it.
{
  const rr = u * (0.54 + 0.12 * dr3);
  const gd = ctx.createRadialGradient(REFX, REFY, 0, REFX, REFY, rr);
  const gi = (0.070 + 0.160 * P.energy) * aa * (0.85 + K.swell * 0.3);
  gd.addColorStop(0, 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',' + gi.toFixed(3) + ')');
  gd.addColorStop(1, 'rgba(' + SPEC[0] + ',' + SPEC[1] + ',' + SPEC[2] + ',0)');
  ctx.fillStyle = gd; ctx.fillRect(REFX - rr, REFY - rr, rr * 2, rr * 2);
}
ctx.restore();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
